  /// Center coordinates of Sadat City
  static const LatLng cityCenter = LatLng(30.3789, 30.5182);

  /// Geographic bounding box defining Sadat City and its contiguous municipal boundaries
  static const double minLat = 30.2200;
  static const double maxLat = 30.5500;
  static const double minLng = 30.3200;
  static const double maxLng = 30.7200;

  /// Checks whether a given coordinate point falls within Sadat City's metropolitan perimeter
  static bool isInSadatCity(double lat, double lng) {
    return lat >= minLat && lat <= maxLat && lng >= minLng && lng <= maxLng;
  }

  /// Calculates Haversine distance in meters between two geographical points
  static double distanceBetweenMeters(double lat1, double lon1, double lat2, double lon2) {
    const double r = 6371000.0; // Earth radius in meters
    final double dLat = _toRadians(lat2 - lat1);
    final double dLon = _toRadians(lon2 - lon1);
    final double a = sin(dLat / 2) * sin(dLat / 2) +
        cos(_toRadians(lat1)) * cos(_toRadians(lat2)) * sin(dLon / 2) * sin(dLon / 2);
    final double c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return r * c;
  }

  static double _toRadians(double degree) => degree * pi / 180.0;

  /// Calculates Haversine distance in kilometers between two geographical points
  static double calculateDistance(double lat1, double lon1, double lat2, double lon2) {
    return distanceBetweenMeters(lat1, lon1, lat2, lon2) / 1000.0;
  }

  /// Returns full list of curated places converted to [PlaceLocation]
  static List<PlaceLocation> getAllPlaces({double? userLat, double? userLng}) {
    final double refLat = userLat ?? cityCenter.latitude;
    final double refLng = userLng ?? cityCenter.longitude;

    return _rawPlaces.map((item) {
      final double lat = (item['lat'] as num).toDouble();
      final double lng = (item['lng'] as num).toDouble();
      final double distMeters = distanceBetweenMeters(refLat, refLng, lat, lng);
      final double distKm = distMeters / 1000.0;

      return PlaceLocation(
        placeId: item['place_id'] as String? ?? 'sadat_${item['id']}',
        latitude: lat,
        longitude: lng,
        placeName: item['name'] as String,
        formattedAddress: item['address'] as String,
        category: item['category'] as String? ?? 'landmark',
        subCategory: item['sub_category'] as String?,
        placeType: item['place_type'] as String? ?? 'residential_area',
        city: item['city'] as String? ?? 'مدينة السادات',
        district: item['district'] as String?,
        mallName: item['mall_name'] as String?,
        phone: item['phone'] as String?,
        coordinatesVerified: item['coordinates_verified'] as bool? ?? true,
        source: item['source'] as String? ?? 'OpenStreetMap',
        aliases: (item['aliases'] as List<dynamic>?)?.map((e) => e.toString()).toList() ?? const [],
        nameAr: item['name_ar'] as String? ?? item['name'] as String,
        nameEn: item['name_en'] as String?,
        timestamp: DateTime.now(),
        distanceKm: double.parse(distKm.toStringAsFixed(2)),
        distanceMeters: double.parse(distMeters.toStringAsFixed(1)),
        popularity: (item['popularity'] as num?)?.toInt() ?? 80,
      );
    }).toList();
  }

