  /// Levenshtein edit distance between two strings
  static int levenshteinDistance(String s1, String s2) {
    if (s1 == s2) return 0;
    if (s1.isEmpty) return s2.length;
    if (s2.isEmpty) return s1.length;

    List<int> v0 = List<int>.generate(s2.length + 1, (i) => i);
    List<int> v1 = List<int>.filled(s2.length + 1, 0);

    for (int i = 0; i < s1.length; i++) {
      v1[0] = i + 1;
      for (int j = 0; j < s2.length; j++) {
        final int cost = (s1[i] == s2[j]) ? 0 : 1;
        v1[j + 1] = min(v1[j] + 1, min(v0[j + 1] + 1, v0[j] + cost));
      }
      for (int j = 0; j <= s2.length; j++) {
        v0[j] = v1[j];
      }
    }
    return v1[s2.length];
  }

  /// Strips Arabic definite article ('ال' / 'الـ')
  static String stripArticle(String word) {
    if (word.length >= 4 && (word.startsWith('ال') || word.startsWith('أل') || word.startsWith('إل'))) {
      return word.substring(2);
    }
    return word;
  }

  /// Measures fuzzy similarity between two tokens [0.0 - 1.0]
  static double tokenSimilarity(String t1, String t2) {
    if (t1.isEmpty || t2.isEmpty) return 0.0;
    if (t1 == t2) return 1.0;

    final minLen = min(t1.length, t2.length);
    final maxLen = max(t1.length, t2.length);

    // Direct root match without 'ال'
    final stripped1 = stripArticle(t1);
    final stripped2 = stripArticle(t2);
    if (stripped1 == stripped2 && stripped1.isNotEmpty) return 0.98;

    // For short tokens (<= 2 chars, like numbers or prepositions), require exact equality
    if (minLen <= 2) {
      return 0.0;
    }

    // Prefix match (only when lengths are sufficiently close)
    if (minLen >= 3 && (minLen / maxLen) >= 0.60) {
      if (t1.startsWith(t2) || t2.startsWith(t1)) {
        return 0.85 + (0.10 * (minLen / maxLen));
      }
    }

    // Substring match (only when length difference <= 3)
    if (minLen >= 3 && (maxLen - minLen) <= 3) {
      if (t1.contains(t2) || t2.contains(t1)) {
        return 0.80 + (0.10 * (minLen / maxLen));
      }
    }

    // Stripped prefix/contains match
    if (stripped1.length >= 3 && stripped2.length >= 3 && (max(stripped1.length, stripped2.length) - min(stripped1.length, stripped2.length)) <= 3) {
      if (stripped1.startsWith(stripped2) || stripped2.startsWith(stripped1)) return 0.88;
      if (stripped1.contains(stripped2) || stripped2.contains(stripped1)) return 0.82;
    }

    // Levenshtein edit distance comparison
    final dist = levenshteinDistance(t1, t2);

    if (maxLen <= 3) {
      return 0.0;
    } else if (maxLen <= 5) {
      if (dist <= 1) return 1.0 - (dist / maxLen);
      return 0.0;
    } else {
      if (dist <= 2) return 1.0 - (dist / maxLen);
      return 0.0;
    }
  }

  /// Calculates token-level fuzzy match score against target texts
  static double computeTokenScore({
    required List<String> queryTokens,
    required List<String> targetTokens,
  }) {
    if (queryTokens.isEmpty || targetTokens.isEmpty) return 0.0;

    double matchedWeight = 0.0;
    for (final qToken in queryTokens) {
      double bestSim = 0.0;
      for (final tToken in targetTokens) {
        final sim = tokenSimilarity(qToken, tToken);
        if (sim > bestSim) bestSim = sim;
      }
      if (bestSim >= 0.70) {
        matchedWeight += bestSim;
      }
    }

    final ratio = matchedWeight / queryTokens.length;
    if (ratio >= 0.90) return 85.0 * ratio;
    if (ratio >= 0.50) return 65.0 * ratio;
    if (queryTokens.length == 1 && matchedWeight >= 0.70) return 55.0 * matchedWeight;

    return 0.0;
  }

  /// Fast local smart search with fuzzy matching, spelling error tolerance, and proximity ranking
  static List<PlaceLocation> searchLocal({
    required String query,
    required double userLat,
    required double userLng,
    int limit = 15,
  }) {
    final String cleanQuery = normalizeArabic(query);
    if (cleanQuery.isEmpty) {
      return getTopNearbyPlaces(userLat: userLat, userLng: userLng, limit: limit);
    }

    final String phoneticQuery = phoneticNormalize(cleanQuery);
    final List<String> queryTokens = cleanQuery.split(' ').where((t) => t.length > 1).toList();
    final List<String> phoneticTokens = phoneticQuery.split(' ').where((t) => t.length > 1).toList();

    // Check if query matches any category intent (e.g. 'سوبر ماركت', 'مطاعم', 'صيدليات')
    String? matchedCategory;
    for (final entry in categoryIntentKeywords.entries) {
      for (final kw in entry.value) {
        final normKw = normalizeArabic(kw);
        if (cleanQuery == normKw || cleanQuery.startsWith(normKw) || normKw.startsWith(cleanQuery)) {
          matchedCategory = entry.key;
          break;
        }
      }
      if (matchedCategory != null) break;
    }

    final List<Map<String, dynamic>> scored = [];

    for (final raw in _rawPlaces) {
      final String rawName = raw['name'] as String;
      final String rawAddr = raw['address'] as String;
      final String nameNorm = normalizeArabic(rawName);
      final String addrNorm = normalizeArabic(rawAddr);
      final String namePhonetic = phoneticNormalize(rawName);
      final String addrPhonetic = phoneticNormalize(rawAddr);

      final List<String> aliases = (raw['aliases'] as List<dynamic>?)
              ?.map((a) => normalizeArabic(a.toString()))
              .toList() ??
          [];
      final List<String> aliasesPhonetic = (raw['aliases'] as List<dynamic>?)
              ?.map((a) => phoneticNormalize(a.toString()))
              .toList() ??
          [];

      double matchScore = 0.0;

      // 0. Category intent matching (e.g. searching 'سوبر ماركت' matches all supermarkets)
      final String rawCat = (raw['category'] as String? ?? '').toLowerCase();
      final String rawSubCat = (raw['sub_category'] as String? ?? '').toLowerCase();
      if (matchedCategory != null && (rawCat == matchedCategory || rawSubCat == matchedCategory)) {
        matchScore = 85.0;
      }

      // Check shop inside mall match (e.g. searching mall name matches shops inside it)
      final String? mallName = raw['mall_name'] as String?;
      if (mallName != null && normalizeArabic(mallName).contains(cleanQuery)) {
        matchScore = max(matchScore, 78.0);
      }

      // Check district match
      final String? district = raw['district'] as String?;
      if (district != null && normalizeArabic(district).contains(cleanQuery)) {
        matchScore = max(matchScore, 70.0);
      }

      // 1. Exact match on clean name or alias
      if (nameNorm == cleanQuery || aliases.any((a) => a == cleanQuery)) {
        matchScore = max(matchScore, 100.0);
      }
      // 2. Exact match on phonetic normalized name or alias
      else if (namePhonetic == phoneticQuery || aliasesPhonetic.any((a) => a == phoneticQuery)) {
        matchScore = max(matchScore, 95.0);
      }
      // 3. Name or alias starts with query
      else if (nameNorm.startsWith(cleanQuery) || aliases.any((a) => a.startsWith(cleanQuery)) ||
               namePhonetic.startsWith(phoneticQuery) || aliasesPhonetic.any((a) => a.startsWith(phoneticQuery))) {
        matchScore = max(matchScore, 90.0);
      }
      // 4. Name or alias contains query phrase
      else if (nameNorm.contains(cleanQuery) || aliases.any((a) => a.contains(cleanQuery)) ||
               namePhonetic.contains(phoneticQuery) || aliasesPhonetic.any((a) => a.contains(phoneticQuery))) {
        matchScore = max(matchScore, 80.0);
      }
      // 5. Address contains full query phrase
      else if (addrNorm.contains(cleanQuery) || addrPhonetic.contains(phoneticQuery)) {
        matchScore = max(matchScore, 70.0);
      }
      // 6. Fuzzy token-level evaluation (spelling errors, typo tolerance, swapped words)
      else {
        final List<String> targetTokens = [
          ...nameNorm.split(' '),
          ...addrNorm.split(' '),
          ...aliases.expand((a) => a.split(' ')),
          ...namePhonetic.split(' '),
          ...aliasesPhonetic.expand((a) => a.split(' ')),
        ].where((t) => t.length > 1).toSet().toList();

        final fScoreNorm = computeTokenScore(queryTokens: queryTokens, targetTokens: targetTokens);
        final fScorePhon = computeTokenScore(queryTokens: phoneticTokens, targetTokens: targetTokens);
        matchScore = max(matchScore, max(fScoreNorm, fScorePhon));
      }

      // CRITICAL: Reject completely if there is no text/fuzzy match!
      if (matchScore >= 35.0) {
        final double lat = (raw['lat'] as num).toDouble();
        final double lng = (raw['lng'] as num).toDouble();
        final double distMeters = distanceBetweenMeters(userLat, userLng, lat, lng);
        final double distKm = distMeters / 1000.0;

        // Proximity bonus: up to +20 points for close places (< 5 km)
        final double proximityBonus = max(0.0, 20.0 * (1.0 - (distKm / 25.0)));
        final int popularity = (raw['popularity'] as num?)?.toInt() ?? 80;
        final double popularityBonus = (popularity / 100.0) * 5.0;

        final double finalScore = matchScore + proximityBonus + popularityBonus;

        scored.add({
          'raw': raw,
          'lat': lat,
          'lng': lng,
          'distMeters': distMeters,
          'distKm': distKm,
          'finalScore': finalScore,
        });
      }
    }

    // Sort descending by finalScore, then ascending by distance
    scored.sort((a, b) {
      final double scoreA = a['finalScore'] as double;
      final double scoreB = b['finalScore'] as double;
      if ((scoreB - scoreA).abs() > 4.0) {
        return scoreB.compareTo(scoreA);
      }
      return (a['distMeters'] as double).compareTo(b['distMeters'] as double);
    });

    return scored.take(limit).map((entry) {
      final raw = entry['raw'] as Map<String, dynamic>;
      final double lat = entry['lat'] as double;
      final double lng = entry['lng'] as double;
      final double distKm = entry['distKm'] as double;
      final double distMeters = entry['distMeters'] as double;

      return PlaceLocation(
        placeId: raw['place_id'] as String? ?? 'sadat_${raw['id']}',
        latitude: lat,
        longitude: lng,
        placeName: raw['name'] as String,
        formattedAddress: raw['address'] as String,
        category: raw['category'] as String? ?? 'landmark',
        subCategory: raw['sub_category'] as String?,
        placeType: raw['place_type'] as String? ?? 'residential_area',
        city: raw['city'] as String? ?? 'مدينة السادات',
        district: raw['district'] as String?,
        mallName: raw['mall_name'] as String?,
        phone: raw['phone'] as String?,
        coordinatesVerified: raw['coordinates_verified'] as bool? ?? true,
        source: raw['source'] as String? ?? 'OpenStreetMap',
        aliases: (raw['aliases'] as List<dynamic>?)?.map((e) => e.toString()).toList() ?? const [],
        nameAr: raw['name_ar'] as String? ?? raw['name'] as String,
        nameEn: raw['name_en'] as String?,
        timestamp: DateTime.now(),
        distanceKm: double.parse(distKm.toStringAsFixed(1)),
        distanceMeters: double.parse(distMeters.toStringAsFixed(0)),
        popularity: (raw['popularity'] as num?)?.toInt() ?? 80,
        finalScore: entry['finalScore'] as double,
      );
    }).toList();
  }

  /// Returns top popular reference places near user inside Sadat City
  static List<PlaceLocation> getTopNearbyPlaces({
    required double userLat,
    required double userLng,
    int limit = 12,
  }) {
    final List<Map<String, dynamic>> list = [];

    for (final raw in _rawPlaces) {
      final double lat = (raw['lat'] as num).toDouble();
      final double lng = (raw['lng'] as num).toDouble();
      final double distMeters = distanceBetweenMeters(userLat, userLng, lat, lng);
      final double distKm = distMeters / 1000.0;
      final int pop = (raw['popularity'] as num?)?.toInt() ?? 80;

      list.add({
        'raw': raw,
        'lat': lat,
        'lng': lng,
        'distMeters': distMeters,
        'distKm': distKm,
        'popularity': pop,
      });
    }

    // Sort by proximity primarily
    list.sort((a, b) {
      final double distA = a['distMeters'] as double;
      final double distB = b['distMeters'] as double;
      return distA.compareTo(distB);
    });

    return list.take(limit).map((entry) {
      final raw = entry['raw'] as Map<String, dynamic>;
      final double lat = entry['lat'] as double;
      final double lng = entry['lng'] as double;
      final double distKm = entry['distKm'] as double;
      final double distMeters = entry['distMeters'] as double;

      return PlaceLocation(
        placeId: raw['place_id'] as String? ?? 'sadat_${raw['id']}',
        latitude: lat,
        longitude: lng,
        placeName: raw['name'] as String,
        formattedAddress: raw['address'] as String,
        category: raw['category'] as String? ?? 'landmark',
        placeType: raw['place_type'] as String? ?? 'residential_area',
        city: raw['city'] as String? ?? 'مدينة السادات',
        coordinatesVerified: raw['coordinates_verified'] as bool? ?? true,
        source: raw['source'] as String? ?? 'OpenStreetMap',
        aliases: (raw['aliases'] as List<dynamic>?)?.map((e) => e.toString()).toList() ?? const [],
        nameAr: raw['name_ar'] as String? ?? raw['name'] as String,
        nameEn: raw['name_en'] as String?,
        timestamp: DateTime.now(),
        distanceKm: double.parse(distKm.toStringAsFixed(1)),
        distanceMeters: double.parse(distMeters.toStringAsFixed(0)),
        popularity: entry['popularity'] as int,
      );
    }).toList();
  }

  /// Robust Arabic normalization helper for search matching
  static String normalizeArabic(String text) {
    if (text.isEmpty) return '';
    var s = text.toLowerCase().trim();

    // Convert Hindi / Eastern Arabic numerals (٠-٩) to standard digits (0-9) FIRST
    const hindiDigits = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
    for (int i = 0; i < 10; i++) {
      s = s.replaceAll(hindiDigits[i], '$i');
    }

    // Separate digits from adjacent Arabic letters (e.g. 'منطقة21' -> 'منطقة 21', 'حي7' -> 'حي 7')
    s = s.replaceAllMapped(RegExp(r'([^\d\s])(\d+)'), (m) => '${m[1]} ${m[2]}');
    s = s.replaceAllMapped(RegExp(r'(\d+)([^\d\s])'), (m) => '${m[1]} ${m[2]}');

    // Normalize Alif variations (أ, إ, آ, ٱ -> ا)
    s = s.replaceAll(RegExp(r'[إأآٱ]'), 'ا');

    // Normalize Taa Marbuta & Haa (ة -> ه)
    s = s.replaceAll('ة', 'ه');

    // Normalize Yaa & Alif Maqsura (ى -> ي)
    s = s.replaceAll('ى', 'ي');

    // Normalize Hamza forms (ئ, ؤ, ء -> ا)
    s = s.replaceAll(RegExp(r'[ئؤء]'), 'ا');

    // Remove Arabic diacritics / Tashkeel & Tatweel (ـ)
    s = s.replaceAll(RegExp(r'[\u064B-\u065F\u0670\u0640]'), '');

    // Normalize punctuation and symbols to spaces
    s = s.replaceAll(RegExp(r'[-_/\\.,;:()\[\]{}+*#@!؟?]'), ' ');

    // Collapse multiple whitespace
    s = s.replaceAll(RegExp(r'\s+'), ' ');

    return s.trim();
  }

  /// Extended phonetic & ordinal word normalization (e.g. ذ -> ز, الحادية والعشرون -> 21)
  static String phoneticNormalize(String text) {
    if (text.isEmpty) return '';
    var s = normalizeArabic(text);

    // Phonetic swaps common in Egyptian dialect typing
    s = s.replaceAll('ذ', 'ز');
    s = s.replaceAll('ظ', 'ض');
    s = s.replaceAll('ث', 'س');

    // Split words to safely map Arabic compound and single ordinal numbers to digits
    final words = s.split(' ');
    final mapped = <String>[];
    for (int i = 0; i < words.length; i++) {
      final w = words[i];

      // Check compound numbers with "و" like "الحادية والعشرون" / "واحد وعشرين"
      if (i + 1 < words.length && (words[i + 1].startsWith('و') || words[i + 1].startsWith('وال'))) {
        final next = words[i + 1].replaceFirst(RegExp(r'^و(ال)?'), '');
        final first = w.replaceFirst(RegExp(r'^(ال)?'), '');

        int? tens;
        if (next == 'عشرون' || next == 'عشرين') {
          tens = 20;
        } else if (next == 'ثلاثون' || next == 'ثلاثين' || next == 'تلاتون' || next == 'تلاتين') {
          tens = 30;
        }

        if (tens != null) {
          int? unit;
          if (first == 'حادي' || first == 'حاديه' || first == 'واحد' || first == 'واحده') {
            unit = 1;
          } else if (first == 'ثاني' || first == 'ثانيه' || first == 'تاني' || first == 'تانيه' || first == 'اثنين' || first == 'اتنين') {
            unit = 2;
          } else if (first == 'ثالث' || first == 'ثالثه' || first == 'تالت' || first == 'تالته' || first == 'ثلاثه' || first == 'تلاته') {
            unit = 3;
          } else if (first == 'رابع' || first == 'رابعه' || first == 'اربعه' || first == 'اربعة') {
            unit = 4;
          } else if (first == 'خامس' || first == 'خامسه' || first == 'خمسه' || first == 'خمسة') {
            unit = 5;
          } else if (first == 'سادس' || first == 'سادسه' || first == 'سته' || first == 'ستة') {
            unit = 6;
          } else if (first == 'سابع' || first == 'سابعه' || first == 'سبعه' || first == 'سبعة') {
            unit = 7;
          } else if (first == 'ثامن' || first == 'ثامنه' || first == 'تامن' || first == 'تامنه' || first == 'ثمانيه' || first == 'تمانيه') {
            unit = 8;
          } else if (first == 'تاسع' || first == 'تاسعه' || first == 'تسعه' || first == 'تسعة') {
            unit = 9;
          }

          if (unit != null) {
            mapped.add('${tens + unit}');
            i++;
            continue;
          }
        }
      }

      // Check compound ordinal numbers like 'الحادي عشر', 'الثاني عشر'
      if (i + 1 < words.length && (words[i + 1] == 'عشر' || words[i + 1] == 'عشره')) {
        if (w == 'الحادي' || w == 'الحاديه' || w == 'حادي') { mapped.add('11'); i++; continue; }
        else if (w == 'الثاني' || w == 'الثانيه' || w == 'ثاني') { mapped.add('12'); i++; continue; }
        else if (w == 'الثالث' || w == 'الثالثه' || w == 'ثالث') { mapped.add('13'); i++; continue; }
        else if (w == 'الرابع' || w == 'الرابعه' || w == 'رابع') { mapped.add('14'); i++; continue; }
        else if (w == 'الخامس' || w == 'الخامسه' || w == 'خامس') { mapped.add('15'); i++; continue; }
        else if (w == 'السادس' || w == 'السادسه' || w == 'سادس') { mapped.add('16'); i++; continue; }
        else if (w == 'السابع' || w == 'السابعه' || w == 'سابع') { mapped.add('17'); i++; continue; }
        else if (w == 'الثامن' || w == 'الثامنه' || w == 'ثامن') { mapped.add('18'); i++; continue; }
        else if (w == 'التاسع' || w == 'التاسعه' || w == 'تاسع') { mapped.add('19'); i++; continue; }
      }

      switch (w) {
        case 'الاول':
        case 'الاولى':
        case 'اول':
        case 'اولى':
          mapped.add('1');
          break;
        case 'الثاني':
        case 'الثانيه':
        case 'ثاني':
        case 'ثانيه':
        case 'تاني':
        case 'تانيه':
          mapped.add('2');
          break;
        case 'الثالث':
        case 'الثالثه':
        case 'ثالث':
        case 'ثالثه':
        case 'تالت':
        case 'تالته':
          mapped.add('3');
          break;
        case 'الرابع':
        case 'الرابعه':
        case 'رابع':
        case 'رابعه':
          mapped.add('4');
          break;
        case 'الخامس':
        case 'الخامسه':
        case 'خامس':
        case 'خامسه':
          mapped.add('5');
          break;
        case 'السادس':
        case 'السادسه':
        case 'سادس':
        case 'سادسه':
          mapped.add('6');
          break;
        case 'السابع':
        case 'السابعه':
        case 'سابع':
        case 'سابعه':
          mapped.add('7');
          break;
        case 'الثامن':
        case 'الثامنه':
        case 'ثامن':
        case 'ثامنه':
        case 'تامن':
        case 'تامنه':
          mapped.add('8');
          break;
        case 'التاسع':
        case 'التاسعه':
        case 'تاسع':
        case 'تاسعه':
          mapped.add('9');
          break;
        case 'العاشر':
        case 'العاشره':
        case 'عاشر':
        case 'عاشره':
          mapped.add('10');
          break;
        case 'العشرون':
        case 'العشرين':
        case 'عشرون':
        case 'عشرين':
          mapped.add('20');
          break;
        case 'الثلاثون':
        case 'الثلاثين':
        case 'ثلاثون':
        case 'ثلاثين':
        case 'تلاتون':
        case 'تلاتين':
          mapped.add('30');
          break;
        default:
          mapped.add(w);
      }
    }

    return mapped.join(' ').trim();
  }
}
